from dataclasses import dataclass
from fastapi import APIRouter, Header, HTTPException
from app.auth import decode_access_token
from app.events import event_store
from app.policy import authorize
from app.queue import tasks
from app.publisher import publisher

router = APIRouter()

@dataclass
class SecurityContext:
    subject: str
    tenant_id: str
    scopes: set[str]

def build_context(authorization: str) -> SecurityContext:
    if not authorization.startswith('Bearer '):
        raise HTTPException(status_code=401, detail='missing bearer token')
    claims = decode_access_token(authorization[7:])
    if claims is None:
        raise HTTPException(status_code=401, detail='invalid token')
    return SecurityContext(
        subject=claims['sub'],
        tenant_id=claims['tenant_id'],
        scopes=set(claims.get('scopes', )),
    )

@router.post('/v1/events/{event_id}/retry')
def retry_event(event_id: str, authorization: str = Header(...)) -> dict:
    ctx = build_context(authorization)
    event = event_store.get(event_id)
    if event is None or event.tenant_id != ctx.tenant_id:
        raise HTTPException(status_code=404, detail='event not found')
    authorize(ctx, 'events:retry', event.topic)
    tasks.enqueue(retry_in_background, event_id)
    return {'queued': True}

def retry_in_background(event_id: str) -> None:
    event = event_store.get(event_id)
    if event is None:
        return
    publisher.publish(topic=event.topic, payload=event.payload)

@router.post('/admin/keys/rotate')
def rotate_keys(authorization: str = Header(...)) -> dict:
    ctx = build_context(authorization)
    authorize(ctx, 'keys:rotate', 'platform')
    event_store.rotate_signing_key()
    return {'rotated': True}

